/* Searchable authoring controls. All changes stay in the local draft. */
let authorPickerSelect=null,authorPickerTarget=null;
function authorTypeLabel(type){return type==='Catalogue'?'Shared dropdown':type}
function authorInsertOptions(id,key){
 const n=sop().nodes.find(n=>n.id===id);if(!n||!canEdit())return;
 const sources=typeof visibleSources==='function'?visibleSources(current):[];
 modal('Add a question or next step',`<p>After <strong>${esc(n.label)}</strong></p><label class="field"><span>Your question</span><input id="author-question-title" aria-label="New question text" placeholder="Type your own question…"></label><input aria-label="Search question types or shared lists" placeholder="Search types, medicines, vaccines, vendors…" oninput="authorFilter(this.value)"><h3>Choose how the operator answers</h3><div class="author-type-grid">${questionnaireTypes.map(t=>`<button data-author-search="${esc(authorTypeLabel(t).toLowerCase())}" onclick="authorInsert('${id}','${key}','${t}')">${esc(authorTypeLabel(t))}<small>${esc(({Number:'Units and optional input limits','Yes / No':'Two answer choices','Single choice':'Write your own options','Multiple choice':'Select several answers',Catalogue:'Use a shared list',Text:'Free text answer',Date:'Pick a date',Photo:'Capture evidence',Video:'Record evidence','Photo or video':'Either capture type'})[t]||'')}</small></button>`).join('')}</div><h3>Or add workflow logic</h3><div class="actions"><button onclick="canvasInsert('${id}','${key}','condition')">◇ Condition / Branch · &gt; &lt; = ≠</button><button onclick="canvasInsert('${id}','${key}','action')">↳ Action / instruction</button></div><h3>Shared lists available to ${esc(current)}</h3><div class="author-source-list">${sources.map(s=>`<button data-author-search="${esc((s.owner+' '+s.name).toLowerCase())}" onclick="authorInsert('${id}','${key}','Catalogue','${s.id}')"><span>${esc(s.name)}</span><small>${esc(s.owner)} · ${sourceOptions(s,current).length} active choices</small></button>`).join('')||'<p>No lists shared with this module yet. Configure availability in Shared Config.</p>'}</div><p id="author-no-results" hidden>No matching types or shared lists.</p><p class="muted">Write custom questions and choices. Shared dropdowns use the owner’s configured records.</p>`);
}
canvasInsertMenu=authorInsertOptions;
function authorFilter(value){let count=0;document.querySelectorAll('[data-author-search]').forEach(el=>{el.hidden=!el.dataset.authorSearch.includes(value.toLowerCase().trim());if(!el.hidden)count++});const none=document.getElementById('author-no-results');if(none)none.hidden=!!count}
function authorInsert(id,key,type,sourceId){
 if(typeof qrManagedPort==='function'&&qrManagedPort(id,key))return toast('Choose a branch outcome to insert a step.');
 const existingIds=new Set(sop().nodes.map(n=>n.id)),parent=sop().nodes.find(n=>n.id===id),title=document.getElementById('author-question-title')?.value.trim();insertTypedQuestion(id,key,type);const q=sop().nodes.find(n=>n.id===selected);if(!q||q.type!=='question'||existingIds.has(q.id))return;
 for(const k of ['sourceScope','sourcePage','sourcePageTitle'])if(parent?.[k]!==undefined)q[k]=parent[k];if(title)q.label=title;if(type==='Number'){q.min=null;q.max=null;q.unit='';q.unitOptional=true}if(sourceId){q.catalogueSourceId=sourceId;const source=sourceById(sourceId);if(!title)q.label='Select '+source.name.toLowerCase()}
 persist();drawGraph();inspect();const input=document.querySelector('#inspector [aria-label="Question title"],#inspector input');input?.focus();
}
function authorEnhanceQuestionSelectors(){
 const panel=document.getElementById('inspector');if(!panel)return;const ids=new Set(sop().nodes.filter(n=>n.type==='question').map(n=>n.id));
 panel.querySelectorAll('select').forEach(select=>{
  if(select.dataset.authorPicker||select.options.length<1)return;const values=Array.from(select.options).map(o=>o.value).filter(Boolean);if(!values.length||!values.every(v=>ids.has(v)))return;
  const aria=select.getAttribute('aria-label')||'';if(/destination|next|otherwise|target/i.test(aria))return;
  select.dataset.authorPicker='true';select.hidden=true;const button=document.createElement('button');button.type='button';button.className='author-question-picker';button.disabled=select.disabled;button.setAttribute('aria-label','Choose answer question: '+(select.selectedOptions[0]?.textContent||'Choose question'));button.textContent=(select.selectedOptions[0]?.textContent||'Choose question')+'  ⌕';button.onclick=()=>openQuestionSourcePicker(select);select.insertAdjacentElement('afterend',button);
 });
}
function openQuestionSourcePicker(select){authorPickerSelect=select;authorPickerTarget=selected;modal('Which answer should this rule check?',`<p>Select an existing question or create your own.</p><input aria-label="Search existing questions" placeholder="Search question name or page…" oninput="authorFilter(this.value)"><div class="author-question-results">${sop().nodes.filter(q=>q.type==='question').map(q=>`<button data-author-search="${esc((q.label+' '+(q.sourcePage||'')).toLowerCase())}" onclick="authorChooseQuestion('${q.id}')"><strong>${esc(q.label)}</strong><small>${esc(q.answer)}${q.sourcePage?' · '+esc(q.sourcePage):''}</small></button>`).join('')}</div><p id="author-no-results" hidden>No matching questions. Create one below.</p><button class="primary" onclick="authorCustomQuestionForm()">+ Create a custom question</button>`)}
function authorChooseQuestion(id){if(!canEdit()||!authorPickerSelect)return;authorPickerSelect.value=id;authorPickerSelect.dispatchEvent(new Event('change',{bubbles:true}));closeModal();inspect()}
function authorCustomQuestionForm(){modal('Create a question for this rule',`<label class="field"><span>Question</span><input id="author-custom-title" aria-label="Custom question text" placeholder="What is the animal’s temperature?"></label><label class="field"><span>Answer type</span><select id="author-custom-type" aria-label="Custom question answer type">${questionnaireTypes.map(t=>`<option value="${t}" ${t==='Number'?'selected':''}>${esc(authorTypeLabel(t))}</option>`).join('')}</select></label><p>The question will be inserted before this condition. Configure its choices or shared list after creation.</p><button class="primary" onclick="authorCreateQuestion()">Create question and use its answer</button>`)}
function authorCreateQuestion(){
 if(!canEdit())return;const label=document.getElementById('author-custom-title')?.value.trim(),answer=document.getElementById('author-custom-type')?.value;if(!label)return toast('Write the question first.');const nodes=sop().nodes,target=nodes.find(n=>n.id===authorPickerTarget);if(!target)return;const before=JSON.stringify(nodes),id='custom-'+crypto.randomUUID();
 const q={id,type:'question',label,answer,required:true,hint:'',x:(target.x||0)-300,y:target.y||0,next:target.id,min:null,max:null,unit:'',unitOptional:true};if(['Single choice','Multiple choice'].includes(answer))q.options=[{value:'option-1',label:'Option 1'},{value:'option-2',label:'Option 2'}];
 for(const k of ['sourceScope','sourcePage','sourcePageTitle'])if(target[k]!==undefined)q[k]=target[k];for(const n of nodes)for(const port of canvasPorts(n))if(n[port.key]===target.id)n[port.key]=id;nodes.push(q);if(authorPickerSelect){const option=new Option(label,id);authorPickerSelect.add(option);authorPickerSelect.value=id;authorPickerSelect.dispatchEvent(new Event('change',{bubbles:true}));}else target.source=id;
 selected=id;persist();canvasRemember(before);closeModal();drawGraph();inspect();toast('Custom question created. Its answer is linked to the condition.');
}
const authorInspectBase=inspect;inspect=function(){authorInspectBase();authorEnhanceQuestionSelectors()};
